//! 📦️ Playbook-play app — binary document surface (constitutional: pack).
//!
//! `PlaybookSpec`'s `store::DocumentPack` impl is generated by the `dsl::DslDocument` derive on its
//! definition in the kernel crate `s/kernel/playbook/rs` — this crate only re-exposes the
//! encode/decode entry points under the app's own constitutional `pack` slot.

use playbook::PlaybookSpec;
use store::PackError;

/// 📦️ Encodes a `PlaybookSpec` to its binary pack form.
pub fn encode(document: &PlaybookSpec) -> Vec<u8> {
    store::DocumentPack::encode_pack(document)
}

/// 📖️ Decodes a `PlaybookSpec` from its binary pack form.
pub fn decode(bytes: &[u8]) -> Result<PlaybookSpec, PackError> {
    <PlaybookSpec as store::DocumentPack>::decode_pack(bytes)
}

